<?php
$catalogError='';
try{$catalogItems=catalogPrograms();}catch(Throwable $ex){error_log($ex->getMessage());$catalogItems=[];$catalogError='Pencarian dan informasi jadwal sementara belum dapat dimuat.';}
$categories=array_values(array_unique(array_column($catalogItems,'category')));$levels=array_values(array_filter(array_unique(array_column($catalogItems,'level'))));
$search=query('q');$category=query('category');$method=query('method');$level=query('level');$date=query('date');$sort=query('sort');
$catalogItems=array_values(array_filter($catalogItems,fn($p)=>(!$search||mb_stripos($p['title'].' '.$p['subtitle'].' '.$p['description'],$search)!==false)&&(!$category||$p['category']===$category)&&(!$method||($p['method']??'')===$method)&&(!$level||($p['level']??'')===$level)&&(!$date||(!empty($p['nearest_date'])&&$p['nearest_date']>=$date))));
if($sort==='popular')usort($catalogItems,fn($a,$b)=>($b['popularity']??0)<=>($a['popularity']??0));
if($sort==='schedule')usort($catalogItems,fn($a,$b)=>strcmp($a['nearest_date']??'9999',$b['nearest_date']??'9999'));
?>
<section class="public-page" id="catalog-search" style="padding-top:30px;scroll-margin-top:100px"><div class="page-heading"><h2 class="section-title">Cari pelatihan yang sesuai.</h2><p>Gunakan pencarian dan filter untuk membandingkan informasi program.</p></div>
<?php if($catalogError): ?><p class="notice info"><?= e($catalogError) ?></p><?php endif; ?>
<form method="get" action="programs.php#catalog-search" class="filters"><label>Cari program<input type="search" name="q" value="<?= e($search) ?>" placeholder="Nama atau topik pelatihan"></label><label>Kategori<select name="category"><option value="">Semua kategori</option><?php foreach($categories as $option): ?><option <?= $category===$option?'selected':'' ?>><?= e($option) ?></option><?php endforeach; ?></select></label><label>Metode<select name="method"><option value="">Semua metode</option><?php foreach(['online'=>'Daring','offline'=>'Tatap muka','hybrid'=>'Hybrid'] as $key=>$label): ?><option value="<?= $key ?>" <?= $method===$key?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><label>Level<select name="level"><option value="">Semua level</option><?php foreach($levels as $option): ?><option <?= $level===$option?'selected':'' ?>><?= e($option) ?></option><?php endforeach; ?></select></label><label>Jadwal mulai dari<input type="date" name="date" value="<?= e($date) ?>"></label><label>Urutkan<select name="sort"><option value="">Urutan program</option><option value="popular" <?= $sort==='popular'?'selected':'' ?>>Pendaftaran disetujui terbanyak</option><option value="schedule" <?= $sort==='schedule'?'selected':'' ?>>Jadwal terdekat</option></select></label><button class="btn" type="submit">Terapkan filter</button><a class="btn secondary" href="programs.php#catalog-search">Reset filter</a></form>
<p class="muted" style="margin-bottom:18px"><?= count($catalogItems) ?> program ditemukan</p><div class="catalog-grid"><?php foreach($catalogItems as $item): ?><article class="panel catalog-card"><img src="<?= e($item['image']) ?>" alt="Ilustrasi <?= e($item['title']) ?>" loading="lazy"><div class="card-body"><span class="badge" style="align-self:start"><?= e($item['category']) ?></span><h2><?= e($item['title']) ?></h2><p class="muted"><?= e($item['subtitle']) ?></p><dl class="meta-list"><div><dt>Metode</dt><dd><?= e(['online'=>'Daring','offline'=>'Tatap muka','hybrid'=>'Hybrid'][$item['method']??'']??'Belum diumumkan') ?></dd></div><div><dt>Durasi</dt><dd><?= e($item['duration']??'Belum diumumkan') ?></dd></div><div><dt>Jadwal resmi terdekat</dt><dd><?= e($item['nearest_date']??'Belum tersedia') ?></dd></div><div><dt>Biaya mulai</dt><dd><?= e(rupiah($item['price']??null)) ?></dd></div></dl><a class="btn" href="program.php?program=<?= e($item['slug']) ?>">Lihat detail program</a></div></article><?php endforeach; ?></div><?php if(!$catalogItems&&!$catalogError): ?><div class="empty"><h2>Belum ada program yang cocok</h2><p>Coba kata kunci lain atau hapus filter untuk melihat seluruh program.</p><a class="btn secondary" href="programs.php#catalog-search">Lihat semua program</a></div><?php endif; ?></section>
